with open(CATALOG_CSV) as f:
    rows=list(csv.DictReader(f))
want={}
for r in rows:
    if r['point_class']=='Zone_Air_Temperature_Sensor':
        z=r['point_uri'].split('#')[1].split('.')[0]
        if z in ('Zone_F4_Z01','Zone_F4_Z02','Zone_F4_Z03','Zone_F4_Z04','Zone_F4_Z05'):
            want[z]=r['timeseries_id']
print(want)
ts='2018-10-10T13:00:00'
res={}
with open(VALUES_CSV) as f:
    r=csv.reader(f); next(r)
    for tsid,t,v in r:
        for z,aid in want.items():
            if tsid==aid and t==ts:
                res[z]=float(v)
print(res)
print("best:", max(res,key=lambda z: res[z]), res[max(res,key=lambda z:res[z])])
